/// <summary>
///
/// </summary>
/// <returns></returns>
public TFMLogicContextTypes outputType()
{
    TFMLogicContextTypes                    ret             = TFMLogicContextTypes::None;
    TFMLogicContextFunctionsDataContract    dc;
    SysDictMethod                           sdm             = new SysDictMethod(UtilElementType::ClassInstanceMethod, classIdGet(this), methodStr(TFMLogicContextFunctions, process));
    ClassName                               contractName;
    DataContractAttribute                   dca             = sdm.getAttribute(classStr(DataContractAttribute));
    MapEnumerator                           mEnum;
    DataMemberAttribute                     dma;


    if (dca && dataContract is TFMLogicContextFunctionsDataContract)
    {
        dc = dataContract;
        contractName = dca.Name();
        mEnum = TFMAttributeHandler::getMethodNamesFromSysAttribute(className2Id(contractName), new DataMemberAttribute(dc.parmKeyName())).getEnumerator();
        while (mEnum.moveNext())
        {
            sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod, className2Id(contractName), mEnum.currentKey());
            dma = sdm.getAttribute(classStr(DataMemberAttribute));
            if (dma && dma.Name() == dc.parmKeyName())
            {
                ret = TFMConditionEditorFormClass::types2ContextType(sdm.returnType());
            }
        }
    }
    return ret;
}

